/** GroupService manages device groups (分组教学). */
export const GroupService = {
  /** AddMember assigns a device to a group. */
  addMember(groupID: string, deviceID: string): Promise<void> {
    return call("GroupService.AddMember", groupID, deviceID);
  },
  /** DeleteGroup removes a group. */
  deleteGroup(groupID: string): Promise<void> {
    return call("GroupService.DeleteGroup", groupID);
  },
  /** ListGroups returns all groups with members. */
  listGroups(): Promise<GroupView[]> {
    return call("GroupService.ListGroups");
  },
  /** RemoveMember unassigns a device from a group. */
  removeMember(groupID: string, deviceID: string): Promise<void> {
    return call("GroupService.RemoveMember", groupID, deviceID);
  },
  /** UpsertGroup adds or renames a group. */
  upsertGroup(groupID: string, name: string): Promise<void> {
    return call("GroupService.UpsertGroup", groupID, name);
  },
} as const;

/** SceneService orchestrates one-click class start/stop (上课/下课). */
export const SceneService = {
  /**
   * StartClass runs the 上课 scene: optional lock, network policy, broadcast
   * and audio, all pushed to students where applicable.
   */
  startClass(opts: ClassSceneOptions): Promise<void> {
    return call("SceneService.StartClass", opts);
  },
  /** StopClass runs the 下课 scene: unlock, network reset, broadcast/audio off. */
  stopClass(): Promise<void> {
    return call("SceneService.StopClass");
  },
} as const;

/** ConfigService exposes the runtime configuration to the settings page. */
export const ConfigService = {
  /** ConfigPath returns the config file location for display. */
  configPath(): Promise<string> {
    return call("ConfigService.ConfigPath");
  },
  /** ExportConfig asks where to save the config and writes it. Returns "" on cancel. */
  exportConfig(): Promise<string> {
    return call("ConfigService.ExportConfig");
  },
  /** FavoriteChannels returns the favorite channel list. */
  favoriteChannels(): Promise<number[]> {
    return call("ConfigService.FavoriteChannels");
  },
  /** Get returns the current configuration. */
  get(): Promise<Config> {
    return call("ConfigService.Get");
  },
  /** ImportConfig opens a TOML file and applies it immediately. */
  importConfig(): Promise<boolean> {
    return call("ConfigService.ImportConfig");
  },
  /** RestoreDefaults resets the config to built-in defaults and applies them. */
  restoreDefaults(): Promise<Config> {
    return call("ConfigService.RestoreDefaults");
  },
  /**
   * Update persists new settings; broadcast changes take effect on the next
   * stream start.
   */
  update(cfg: Config): Promise<void> {
    return call("ConfigService.Update", cfg);
  },
} as const;

/** GroupCastService exposes per-group broadcast scheduling (分组看不同画面). */
export const GroupCastService = {
  /**
   * StartGroupStream starts a group's stream with the given source
   * ("teacher" or a demo device id).
   */
  start(groupID: string, source: string): Promise<void> {
    return call("GroupCastService.Start", groupID, source);
  },
  /** Status lists per-group stream states. */
  status(): Promise<GroupStreamStatus[]> {
    return call("GroupCastService.Status");
  },
  /** StopGroupStream stops one group's stream. */
  stop(groupID: string, source: string): Promise<void> {
    return call("GroupCastService.Stop", groupID, source);
  },
} as const;

// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /** EventAgentAudit carries one agent-reported audit record to the page. */
  agentAudit: event<AgentEvent>("agent:audit"),
  /** EventClassroomDelta carries incremental classroom snapshots. */
  classroomDelta: event<ClassroomDelta>("classroom:delta"),
  /** EventChatMessage carries one classroom chat message. */
  chatMessage: event<ChatMessage>("chat:message"),
  /** EventHandsChanged carries the full active raise-hand queue. */
  handsChanged: event<(HandRecord | null)[]>("hands:changed"),
  /** EventBroadcastMode carries the broadcast session state after a change. */
  broadcastMode: event<BroadcastStatus>("broadcast:mode"),
  /**
   * EventLockStatus carries the screen lock state after any change,
   * including unlocks made from the tray.
   */
  lockStatus: event<LockStatus>("lock:status"),
  /** EventQuizSubmission carries one quiz submission as it arrives. */
  quizSubmission: event<QuizSubmissionNotice>("quiz:submission"),
} as const;
